const menu=document.querySelector('.menu'),nav=document.querySelector('#navigation');function closeMenu(){menu.setAttribute('aria-expanded','false');nav.classList.remove('open')}menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));nav.classList.toggle('open',open)});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu()});document.addEventListener('click',e=>{if(!nav.contains(e.target)&&!menu.contains(e.target))closeMenu()});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));const link=document.querySelector('#project-whatsapp'),interest=document.querySelector('#interest'),a=document.querySelector('#detail-a'),b=document.querySelector('#detail-b');function compose(){const name=link.dataset.person||link.dataset.company;const text='Olá, '+name+'! Gostaria de conversar com '+link.dataset.company+' sobre '+interest.value.toLowerCase()+'.'+(a.value.trim()?' '+document.querySelector('label[for="detail-a"]').childNodes[0].textContent.trim()+': '+a.value.trim()+'.':'')+(b.value.trim()?' '+document.querySelector('label[for="detail-b"]').childNodes[0].textContent.trim()+': '+b.value.trim()+'.':'');link.href='https://wa.me/'+link.dataset.phone+'?text='+encodeURIComponent(text);document.querySelector('#message-preview').textContent='Assunto: '+interest.value+'.'}[interest,a,b].forEach(el=>el.addEventListener('input',compose));document.querySelectorAll('[data-interest]').forEach(el=>el.addEventListener('click',()=>{interest.value=el.dataset.interest;compose()}));compose();const dialog=document.querySelector('#photo-dialog');let opener;document.querySelectorAll('[data-photo]').forEach(el=>el.addEventListener('click',e=>{e.preventDefault();opener=el;document.querySelector('#dialog-image').src=el.getAttribute('href');document.querySelector('#dialog-image').alt=el.querySelector('img').alt;document.querySelector('#dialog-caption').textContent=el.closest('figure').querySelector('figcaption').textContent;dialog.showModal()}));document.querySelector('.close').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>opener?.focus());dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});document.querySelectorAll('.questions details').forEach(d=>d.addEventListener('toggle',()=>{if(d.open)document.querySelectorAll('.questions details').forEach(o=>{if(o!==d)o.open=false})}));if(!matchMedia('(prefers-reduced-motion: reduce)').matches&&'IntersectionObserver'in window){const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('reveal');observer.unobserve(e.target)}}),{threshold:.12});document.querySelectorAll('h2,.section-intro p,.service-list article,.gallery-grid figure,.about p,.about>img,.composer,.contact-photo,.questions details,.area iframe').forEach((el,i)=>{el.style.animationDelay=(i%3)*70+'ms';observer.observe(el)})}
